 payload jsonb:=$master${"version":"0.1-review","status":"structure-approved-not-active","date":"2026-11-26","notes":["Current areas and topics are retained verbatim with their existing IDs.","Recovered keyword ai-automation is assigned distinct canonical keyword ID ai-powered-automation to avoid collision with existing theme; legacyId retained. IDs are typed by layer.","Legacy event mappings are historical associations, not verified report citations. No source report frequency counts available.","Proposed additions are based on inspected editorial intelligence excerpts, programme and speaker research, not a full transcript audit. Source locators identify topics, not verified claims. Definitions and aliases are editorial proposals."],"sources":[{"id":"current","path":"src/content/taxonomy.json","kind":"existing taxonomy"},{"id":"legacy","path":"src/content/keywords.json","documentation":"src/content/README-keywords.md","ref":"364adb5da815caf993833bff40d96affc89bc13a","kind":"recovered vocabulary; original report titles unknown"},{"id":"offair","file":"OFF_AIR_Editorial_Intelligence.xlsx","kind":"editorial evidence index; audio checks outstanding"},{"id":"speaker","file":"OFF_AIR_2026_Speakers_and_Programme_Project_Tracker.xlsx","kind":"speaker research; 29 October 2026; not proof of final participation"},{"id":"programme","file":"OFF_AIR_2026_Working_Programme.docx","kind":"working programme; proposed discussion topics"}],"areas":[{"id":"production","label":"Production","description":"Creating and executing media productions, including production management and craft workflows; distinct from editorial commissioning and ongoing service operations.","active":true},{"id":"operations","label":"Media operations","description":"Running recurring media services, including asset handling, scheduling, operational workflows, service delivery and operational reliability.","active":true},{"id":"content","label":"Content & editorial","description":"Commissioning, acquiring, programming, curating and making editorial decisions about content; distinct from executing production.","active":true},{"id":"distribution-delivery","label":"Distribution & delivery","description":"Getting media to audiences through distribution platforms, channels, delivery systems and associated partnerships.","active":true},{"id":"technology","label":"Engineering & technology","description":"Designing, integrating, developing and maintaining media technology, systems and infrastructure.","active":true},{"id":"commercial","label":"Commercial","description":"Revenue, sales, business development, advertising business, commercial partnerships and commercial rights activity.","active":true},{"id":"strategy-leadership","label":"Strategy & leadership","description":"Organisational direction, executive decision-making, investment priorities and business strategy; not a measure of seniority or invitation eligibility.","active":true}],"themes":[{"id":"monetisation","label":"Monetisation","description":"How media creates revenue and economic value, including subscriptions, transactions, pricing and revenue models; advertising is one mechanism, not a synonym.","active":true,"status":"existing","sourceIds":["current"]},{"id":"discovery","label":"Content discovery","description":"How people find and choose content through search, recommendations, navigation, metadata and prominence; distinct from continuing engagement.","active":true,"status":"existing","sourceIds":["current"]},{"id":"ai-automation","label":"AI & automation","description":"AI applications and automated processes in media; workflow or organisational change does not automatically imply AI.","active":true,"status":"existing","sourceIds":["current"]},{"id":"workflow-transformation","label":"Workflow transformation","description":"Changes to how work moves between people, tools and stages, focusing on processes and implementation rather than organisational structure or culture.","active":true,"status":"existing","sourceIds":["current"]},{"id":"streaming","label":"Streaming","description":"Internet-delivered media services and their operation, product experience and delivery.","active":true,"status":"existing","sourceIds":["current"]},{"id":"cloud-infrastructure","label":"Cloud & infrastructure","description":"Compute, storage, networking, hosting and infrastructure architecture supporting media, including on-premises and hybrid infrastructure.","active":true,"status":"existing","sourceIds":["current"]},{"id":"security","label":"Security","description":"Protecting systems, content, services and information against threats, including access controls and resilience to attacks; not automatically privacy or regulatory compliance.","active":true,"status":"existing","sourceIds":["current"]},{"id":"audience-engagement","label":"Audience engagement","description":"Participation, retention, loyalty and audience relationships; distinct from finding content.","active":true,"status":"existing","sourceIds":["current"]},{"id":"advertising","label":"Advertising","description":"Advertising products, inventory, buying and selling, targeting, delivery and effectiveness; distinct from broader revenue strategy.","active":true,"status":"existing","sourceIds":["current"]},{"id":"rights-licensing","label":"Rights & licensing","description":"Ownership, permissions, exploitation rights, licensing agreements and rights management; not a general legal or compliance category.","active":true,"status":"existing","sourceIds":["current"]},{"id":"data-measurement","label":"Data & measurement","description":"Collecting, managing, analysing and measuring media, business and audience data; apply only where data or measurement is a substantive subject.","active":true,"status":"existing","sourceIds":["current"]},{"id":"organisational-change","label":"Organisational change","description":"Changes to organisational structure, roles, skills, culture and operating models; distinct from changing an individual workflow.","