osed","sourceIds":["speaker"],"evidenceLocator":"Tommy Flanagan"},{"id":"energy-efficiency","label":"Energy efficiency","themeIds":["sustainability-environment"],"description":"Reducing energy use for media production and delivery.","aliases":[],"status":"proposed","sourceIds":["speaker"],"evidenceLocator":"Ian Nock"},{"id":"broadband-connectivity","label":"Broadband connectivity","themeIds":["cloud-infrastructure","streaming"],"description":"Broadband networks supporting media delivery.","aliases":["broadband"],"status":"proposed","sourceIds":["speaker"],"evidenceLocator":"Tommy Flanagan"},{"id":"ai-return-on-investment","label":"AI return on investment","themeIds":["ai-automation","monetisation"],"description":"Assessing AI investment against measurable cost, time and quality outcomes.","aliases":["AI ROI"],"status":"proposed","sourceIds":["programme"],"evidenceLocator":"Survival Guide"},{"id":"media-archives","label":"Media archives","themeIds":["data-measurement","workflow-transformation"],"description":"Preserving and managing media collections for future use.","aliases":["content archives"],"status":"proposed","sourceIds":["speaker"],"evidenceLocator":"Damon Neale"}],"legacyThemes":{"ai-automation":{"label":"AI & Automation","global":["ai-generative","ai-agentic","ai-automation"],"events":{"ibc2026":["ai-generative"],"mpts2026":["ai-generative","ai-automation"],"dpp2026":["ai-agentic","ai-automation"],"personalisedMediaPOC":["ai-automation"]}},"cloud-supply-chain":{"label":"Cloud & Supply Chain","global":["cloud-native-supply-chains","cloud-workflows","camera-to-cloud"],"events":{"ibc2026":["cloud-native-supply-chains","cloud-workflows"],"mpts2026":["cloud-workflows","camera-to-cloud"],"dpp2026":["cloud-native-supply-chains"]}},"personalisation-experience":{"label":"Personalisation & Experience","global":["personalisation","hyper-personalised-experiences","adaptive-narrative","accessibility-inclusivity"],"events":{"ibc2026":["personalisation","hyper-personalised-experiences"],"mpts2026":["personalisation"],"dpp2026":["personalisation"],"personalisedMediaPOC":["hyper-personalised-experiences","adaptive-narrative","accessibility-inclusivity"]}},"metadata-search":{"label":"Metadata & Search","global":["metadata-semantic-tagging","automatic-transcription","entity-extraction","technical-metadata"],"events":{"ibc2026":["metadata-semantic-tagging"],"mpts2026":["technical-metadata"],"dpp2026":["data-driven-insights"],"personalisedMediaPOC":["metadata-semantic-tagging","entity-extraction"]}},"storytelling-search":{"label":"Storytelling & Structured Content","global":["flexible-storytelling","adaptive-narrative"],"events":{"ibc2026":["flexible-storytelling"],"mpts2026":["flexible-storytelling"],"personalisedMediaPOC":["adaptive-narrative"]}},"production-workflows":{"label":"Production & Workflows","global":["virtual-production","live-production","remote-workflows","camera-to-cloud"],"events":{"ibc2026":["live-production","remote-workflows"],"mpts2026":["virtual-production","live-production","camera-to-cloud"]}},"monetisation-fast":{"label":"Monetisation & FAST","global":["fast-monetisation","premium-ad-targeting","content-monetisation"],"events":{"ibc2026":["fast-monetisation","premium-ad-targeting"],"mpts2026":["content-monetisation"],"personalisedMediaPOC":["premium-ad-targeting"]}},"rights-metadata":{"label":"Rights & Asset Management","global":["rights-management","technical-metadata"],"events":{"ibc2026":["rights-management"],"dpp2026":["rights-management"]}},"audience-insights":{"label":"Audience & Insights","global":["creator-economy","data-driven-insights","audience-intelligence"],"events":{"ibc2026":["creator-economy","data-driven-insights"],"mpts2026":["creator-economy"],"dpp2026":["audience-intelligence","data-driven-insights"]}},"security-trust":{"label":"Security & Trust","global":["cyber-security","content-security","trust-transparency"],"events":{"ibc2026":["cyber-security","content-security"],"mpts2026":["cyber-security"],"dpp2026":["trust-transparency"]}},"sustainability-esg":{"label":"Sustainability & ESG","global":["sustainability","diversity-inclusion","accessibility-inclusivity"],"events":{"ibc2026":["sustainability","diversity-inclusion"],"mpts2026":["sustainability"],"dpp2026":["sustainability"]}}},"structureApproval":{"date":"2026-11-26","scope":"Three-layer structure approved by owner; individual proposed terms not automatically activated."}}$master$::jsonb;
 layer record; item jsonb; row_id text; source_id text; theme_id text; alias text; legacy record; event record; keyword text;
begin
 for item in select value from jsonb_array_elements(payload->'sources') loop
  insert into portal_private.taxonomy_sources values(item->>'id',item) on conflict do nothing;
 end loop;
 for layer in select * from (values ('area','areas'),('theme','themes'),('keyword','keywords')) kinds(kind,part) loop
  for item in select value from jsonb_array_elements(payload->layer.part) loop
   row_id:=item->>'id';
   insert into portal_private.taxonomy_terms(id,kind,label,description,status,original_status,evidence_locator,first_activated_at)
   values(row_id,layer.kind,item->>'label',item->>'description',
    case when layer.kind='area' or item->>'status'='existing' then 'active'
    when item->>'status'='recovered-pending-approval' then 'under_review' else 'proposed' end,
    coalesce(item->>'status','existing'),item->>'evidenceLocator',case when layer.kind='area' or item->>'status'='existing' then now() end)
   on conflict do nothing;
   if not found then continue;end if;
   for source_id in select value from jsonb_array_elements_text(coalesce(item->'sourceIds','["current"]'::jsonb)) loop
    insert into portal_private.taxonomy_term_sources values(row_id,source_id) on conflict do nothing;
   end loop;
   for alias in select value from jsonb_array_elements_text(coalesce(item->'aliases','[]'::jsonb)) loop
    insert into portal_private.taxonomy_aliases values(row_id,alias) on conflict do nothing;
   end loop;
   for theme_id in select value from jsonb_array_elements_text(coalesce(item->'themeIds','[]'::jsonb)) loop
    insert into portal_private.taxonomy_relationships values(row_id,theme_id) on conflict do nothing;
   end loop;
   if item ? 'legacyId' then
    insert into portal_private.taxonomy_legacy_ids values(item->>'legacyId',row_id) on conflict do nothing;
   end if;
   insert into portal_private.taxonomy_active_versions(term_id,snapshot)
   select t.id,portal_private.taxonomy_public_record(t) from portal_private.taxonomy_terms t where t.id=row_id and t.status='active' on conflict do nothing;
   insert into portal_private.taxonomy_revisions(term_id,revision,snapshot)
   select t.id,0,portal_private.taxonomy_record(t) from portal_private.taxonomy_terms t where t.id=row_id on conflict do nothing;
  end loop;
 end loop;
 for legacy in select key,value from jsonb_each(payload->'legacyThemes') loop
  for event in select key,value from jsonb_each(coalesce(legacy.value->'events','{}'::jsonb)) loop
   for keyword in select value from jsonb_array_elements_text(event.value) loop
    insert into portal_private.taxonomy_historical_events values(event.key,legacy.key,keyword) on conflict do nothing;
   end loop;
  end loop;
 end loop;
end $seed$;
commit;
